script:
frappe.ui.form.on('Lead', {
    refresh(frm) {
        frm.add_custom_button('Generate Quotes', () => {
            frappe.call({
                method: 'motor_insurance_broker.api.quote_engine.generate_quotes',
                args: {
                    lead_name: frm.doc.name
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.msgprint("Quotes Generated");
                        frappe.set_route('Form', 'Motor Quote', r.message);
                    }
                }
            });
        });
    }
});
